<?php if(empty($prospect)):?><div class="notice danger"><?=e($error??'Prospect introuvable')?></div><?php else:$p=$prospect;$tel=$p['telephone_normalise']?:PhoneNormalizer::normalize($p['telephone'], 'TN');$wa=$tel?'https://wa.me/'.preg_replace('/\D/','',$tel):null;?><div class="back-link"><a href="?r=results">← Retour aux prospects</a></div><div class="page-heading prospect-heading"><div><span class="eyebrow"><?=e($p['categorie'])?> · <?=e($p['ville'])?></span><h1><?=e($p['nom'])?></h1><p><?=e(trim(($p['adresse']??'').' · '.($p['code_postal']??'').' '.($p['ville']??''),' ·'))?></p></div><span class="badge status-<?=$p['statut_prospection']?> large-badge"><?=e(status_label($p['statut_prospection']))?></span></div><div class="action-row"><a class="button primary" href="<?= $tel?'tel:'.e($tel):'#'?>">☎ Appeler</a><a class="button whatsapp" href="<?=e($wa??'#')?>" target="_blank" rel="noopener">◉ WhatsApp</a><a class="button secondary" href="<?= $p['email']?'mailto:'.e($p['email']):'#'?>">✉ Email</a><a class="button secondary" target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat=<?=e($p['latitude'])?>&mlon=<?=e($p['longitude'])?>#map=18/<?=e($p['latitude'])?>/<?=e($p['longitude'])?>">⌖ Itinéraire</a><button class="button secondary" data-verify="<?=$p['id']?>">✓ Vérifier</button><button class="button secondary" data-ai="<?=$p['id']?>">✧ Générer un message</button><button class="button secondary" data-ai-normalize="<?=$p['id']?>">⌁ Normaliser les coordonnées</button></div><div id="action-message" class="hidden"></div><div class="detail-grid"><section class="panel"><div class="panel-heading"><div><h2>Informations du commerce</h2><p><?=($p['osm_type']??'')==='sirene'?'Données administratives de l’Annuaire des Entreprises · SIRET '.e($p['osm_id']):'Coordonnées et informations OpenStreetMap'?></p></div></div><div class="detail-list"><div><span>Téléphone</span><b><?=$tel?'<a href="tel:'.e($tel).'">'.e($p['telephone']?:$tel).'</a>':'Non renseigné'?></b></div><div><span>Email</span><b><?=$p['email']?'<a href="mailto:'.e($p['email']).'">'.e($p['email']).'</a>':'Non renseigné'?></b></div><div><span>Adresse</span><b><?=e($p['adresse']?:'Non renseignée')?></b></div><div><span>Code postal / ville</span><b><?=e(trim(($p['code_postal']??'').' '.($p['ville']??'')))?></b></div><div><span>Facebook</span><b><?=$p['facebook']?'<a target="_blank" rel="noopener" href="'.e(str_starts_with($p['facebook'],'http')?$p['facebook']:'https://facebook.com/'.ltrim($p['facebook'],'@')).'">'.e($p['facebook']).'</a>':'—'?></b></div><div><span>Instagram</span><b><?=$p['instagram']?'<a target="_blank" rel="noopener" href="'.e(str_starts_with($p['instagram'],'http')?$p['instagram']:'https://instagram.com/'.ltrim($p['instagram'],'@')).'">'.e($p['instagram']).'</a>':'—'?></b></div><div><span>Horaires</span><b><?=e($p['horaires']?:'—')?></b></div><div><span>Présence web</span><b><?php if(!empty($p['site_web'])):$webUrl=preg_match('~^https?://~i',$p['site_web'])?$p['site_web']:'https://'.$p['site_web'];?><a href="<?=e($webUrl)?>" target="_blank" rel="noopener"><?=e($p['site_web'])?></a> · <?php endif;?><?=e(['present'=>'Site web','reseaux_sociaux'=>'Réseaux sociaux uniquement','verifie_aucun'=>'Vérifié : aucun','aucun'=>'Non renseigné'][$p['site_web_statut']]??$p['site_web_statut'])?> · confiance <?=e($p['score_confiance'])?></b></div><div><span>Position GPS</span><b><?=e($p['latitude']??'—')?>, <?=e($p['longitude']??'—')?></b></div></div></section><section class="panel"><div class="panel-heading"><div><h2>Suivi commercial</h2><p>Statut, notes et historique</p></div></div><form method="post" action="?r=save_prospect" class="stack-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><label>Statut de prospection<select name="status"><?php foreach(['nouveau','a_contacter','contacte','interesse','rdv','client','refuse'] as $s):?><option value="<?=$s?>" <?=$p['statut_prospection']===$s?'selected':''?>><?=e(status_label($s))?></option><?php endforeach;?></select></label><label>Notes<textarea name="notes" rows="5" placeholder="Notes de suivi…"><?=e($p['notes'])?></textarea></label><button class="button primary">Enregistrer les changements</button></form><hr><h3>Ajouter une interaction</h3><form method="post" action="?r=interaction" class="stack-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><div class="form-row"><select name="type"><option value="appel">Appel</option><option value="whatsapp">WhatsApp</option><option value="email">Email</option><option value="visite">Visite</option></select><input name="note" placeholder="Résumé de l’échange"></div><button class="button secondary">＋ Ajouter au journal</button></form></section></div><section class="panel history-panel"><div class="panel-heading"><div><h2>Historique des interactions</h2><p>Chronologie des actions réalisées</p></div></div><?php if(!$interactions):?><div class="empty-small">Aucune interaction enregistrée.</div><?php endif;foreach($interactions as $i):?><div class="interaction"><span class="interaction-icon">◷</span><div><b><?=e(ucfirst($i['type']))?> · <?=e($i['user_name'])?></b><p><?=e($i['note']?:'Aucune note')?></p><small><?=e(date('d/m/Y à H:i',strtotime($i['date_interaction'])))?></small></div></div><?php endforeach;?></section><?php endif;?>
